// ============================================================================
// test_r18_import.cpp — R18c: SMT / through-hole is decided from drilled pads / holes only (never from a
// declared type or a name), and polarity defaults follow the package class (specs/POLARITY.md).
// All fixtures are synthetic (derived from tests/data/cad, generated by gen_cad_samples.py).
// ============================================================================
#include "../src/io/cad_common.h"
#include "../src/io/gencad.h"
#include "../src/io/io_util.h"
#include "../src/io/ipc2581.h"
#include "../src/io/kicad_pcb.h"
#include "../src/io/odbpp.h"
#include "../src/core/project.h"
#include "../src/core/package_edit.h"
#include "../src/core/pkg_library.h"

#include <cstdio>
#include <cstdlib>
#include <unistd.h>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>

using namespace pcbp;
namespace fs = std::filesystem;

static int g_fail = 0, g_pass = 0;
#define CHECKM(c, m) do { if (c) ++g_pass; else { ++g_fail; std::printf("FAIL %s:%d: %s [%s]\n", __FILE__, __LINE__, #c, std::string(m).c_str()); } } while (0)
#define CHECK(c) CHECKM(c, "")

static std::string slurp(const fs::path& p) { std::ifstream f(p, std::ios::binary); std::stringstream s; s << f.rdbuf(); return s.str(); }
static void spit(const fs::path& p, const std::string& t) { std::ofstream f(p, std::ios::binary); f << t; }
static void replace_all(std::string& s, const std::string& a, const std::string& b) {
    for (size_t at = s.find(a); at != std::string::npos; at = s.find(a, at + b.size())) s.replace(at, a.size(), b);
}
static bool th_of(const Project& p, const char* name) {
    auto it = p.packages.find(name);
    if (it == p.packages.end()) { std::printf("  (package %s missing)\n", name); return false; }
    if (!it->second.smt) return true;
    for (auto& d : it->second.pads) if (d.drill > 0) return true;
    return false;
}

// ODB++: the job's EDA data says SOIC8 pins are "T" (exporter labels every pin through-hole) and a via sits on
// U1 pin 1. SOIC8 must stay SMT; HDR3 (real drilled pins) stays TH.
static void odb_cases() {
    const fs::path src = "tests/data/cad/odb_synth";
    for (int variant = 0; variant < 2; ++variant) {
        const fs::path dst = fs::temp_directory_path() / ("r18c_odb_" + std::to_string(variant) + "_" + std::to_string(::getpid()));
        fs::remove_all(dst);
        fs::copy(src, dst, fs::copy_options::recursive);
        const fs::path eda = dst / "steps/pcb/eda/data";
        std::string e = slurp(eda);
        const size_t a = e.find("PKG SOIC8"), b = e.find("PKG HDR3");
        std::string soic = e.substr(a, b - a);
        if (variant == 0) replace_all(soic, " S ", " T ");      // mislabelled as through-hole, no hole at most pins
        e = e.substr(0, a) + soic + e.substr(b);
        spit(eda, e);
        const fs::path drl = dst / "steps/pcb/layers/drill/features";
        std::string d = slurp(drl);
        replace_all(d, "#\n", "$1 r11.811\n#\n");
        d += "P 1.106102 0.972441 1 P 0 0\n";                    // 0.3 mm via on U1 pin 1 (via in pad)
        spit(drl, d);
        Project p; io::CadImportOptions o; io::CadImportResult r; std::string err;
        const bool ok = io::import_odbpp(dst.string(), p, o, r, err);
        CHECKM(ok, err);
        CHECKM(!th_of(p, "SOIC8"), "ODB++ SOIC8 variant " + std::to_string(variant));
        CHECKM(th_of(p, "HDR3"), "ODB++ HDR3 variant " + std::to_string(variant));
        CHECKM(!th_of(p, "R0805"), "ODB++ R0805");
        fs::remove_all(dst);
    }
}

// IPC-2581: a plated via exactly on U1 pin 1 (SURFACE pins) must not make SOIC8 through-hole.
static void ipc_cases() {
    std::string x = slurp("tests/data/cad/synth.ipc2581.xml");
    const std::string anchor = "<Hole name=\"H14\"";
    const size_t at = x.find(anchor);
    CHECK(at != std::string::npos);
    x.insert(at, "<Hole name=\"VIA1\" diameter=\"0.3\" platingStatus=\"VIA\" plusTol=\"0\" minusTol=\"0\" x=\"28.095\" y=\"24.7\"/>\n          ");
    Project p; io::CadImportOptions o; io::CadImportResult r; std::string err;
    CHECKM(io::import_ipc2581_text(x, p, o, r, err), err);
    CHECKM(!th_of(p, "SOIC8"), "IPC-2581 SOIC8 with via in pad");
    CHECKM(th_of(p, "HDR3"), "IPC-2581 HDR3");
    // a THRU-declared pin with no hole anywhere in a job that has drill data is not TH
    std::string y = slurp("tests/data/cad/synth.ipc2581.xml");
    const size_t s0 = y.find("<Package name=\"SOIC8\""), s1 = y.find("</Package>", s0);
    std::string soic = y.substr(s0, s1 - s0);
    replace_all(soic, "type=\"SURFACE\"", "type=\"THRU\"");
    y = y.substr(0, s0) + soic + y.substr(s1);
    Project q;
    CHECKM(io::import_ipc2581_text(y, q, o, r, err), err);
    CHECKM(!th_of(q, "SOIC8"), "IPC-2581 SOIC8 declared THRU without holes");
}

// GenCAD: INSERT is a declaration; only drills decide.
static void gencad_cases() {
    const std::string g =
        "$HEADER\nGENCAD 1.4\nUNITS MM\n$ENDHEADER\n"
        "$PADS\nPAD P1 ROUND 0.8\nCIRCLE 0 0 0.75\nPAD P2 RECTANGULAR -1\nRECTANGLE -0.5 -0.3 1.0 0.6\n$ENDPADS\n"
        "$PADSTACKS\nPADSTACK PS1 0.9\nPAD P1 TOP 0 0\nPAD P1 BOTTOM 0 0\n$ENDPADSTACKS\n"
        "$SHAPES\nSHAPE SOP64P600X175-16N\nINSERT TH\nPIN 1 P2 -2.7 0 TOP 0 0\nPIN 2 P2 2.7 0 TOP 0 0\nPIN 3 P2 2.7 1.27 TOP 0 0\n"
        "SHAPE HDR2\nINSERT SMD\nPIN 1 PS1 0 0 TOP 0 0\nPIN 2 PS1 2.54 0 TOP 0 0\n$ENDSHAPES\n"
        "$COMPONENTS\nCOMPONENT U1\nPLACE 10 10\nLAYER TOP\nROTATION 0\nSHAPE SOP64P600X175-16N 0 0\n"
        "COMPONENT J1\nPLACE 20 20\nLAYER TOP\nROTATION 0\nSHAPE HDR2 0 0\n$ENDCOMPONENTS\n";
    Project p; io::GencadResult r; std::string err;
    CHECKM(io::import_gencad_text(g, p, {}, r, err), err);
    CHECKM(!th_of(p, "SOP64P600X175-16N"), "GenCAD INSERT TH without drills");
    CHECKM(th_of(p, "HDR2"), "GenCAD drilled padstack with INSERT SMD");
}

// KiCad: smd pads are SMT regardless of the footprint name; thru_hole pads with drills are TH.
static void kicad_cases() {
    const std::string k =
        "(kicad_pcb (version 20221018)\n"
        " (footprint \"lib:DIP8_LOOKALIKE_SOIC\" (layer \"F.Cu\") (at 10 10)\n"
        "  (property \"Reference\" \"U1\")\n"
        "  (pad \"1\" smd rect (at -2.7 1.9) (size 1.5 0.6) (layers \"F.Cu\"))\n"
        "  (pad \"2\" smd rect (at -2.7 0.6) (size 1.5 0.6) (layers \"F.Cu\"))\n"
        "  (pad \"3\" smd rect (at 2.7 0.6) (size 1.5 0.6) (layers \"F.Cu\")))\n"
        " (footprint \"lib:SOIC_NAMED_TH\" (layer \"F.Cu\") (at 20 10)\n"
        "  (property \"Reference\" \"J1\")\n"
        "  (pad \"1\" thru_hole circle (at 0 0) (size 1.7 1.7) (drill 1) (layers \"*.Cu\"))\n"
        "  (pad \"2\" thru_hole circle (at 2.54 0) (size 1.7 1.7) (drill 1) (layers \"*.Cu\"))))\n";
    Project p; io::CadImportOptions o; io::CadImportResult r; std::string err;
    CHECKM(io::import_kicad_pcb_text(k, p, o, r, err), err);
    CHECKM(!th_of(p, "DIP8_LOOKALIKE_SOIC"), "KiCad smd");
    CHECKM(th_of(p, "SOIC_NAMED_TH"), "KiCad thru_hole");
}

// CadBuilder: a type hint without a drill does not make a package TH.
static void builder_cases() {
    io::CadImportResult res;
    io::CadImportOptions o;
    io::CadBuilder b(o, res);
    io::CadPackage cp; cp.name = "HINTED"; cp.th_hint = true;
    io::CadPin a; a.name = "1"; a.pos = {-1, 0}; a.w = a.h = 0.6; a.th_hint = true;
    io::CadPin c = a; c.name = "2"; c.pos = {1, 0};
    cp.pins = {a, c};
    b.add_package(cp);
    Project p; std::string err;
    io::CadComp k; k.ref = "X1"; k.package = "HINTED"; b.add_component(k);
    CHECK(b.commit(p, err));
    CHECKM(!th_of(p, "HINTED"), "th_hint alone");
}

static Package two_pad(const char* name) {
    Package p; p.name = name;
    p.pads = {Pad{{-0.8, 0}, 0.9, 0.95, 0, PadShape::Rect, 0, 1}, Pad{{0.8, 0}, 0.9, 0.95, 0, PadShape::Rect, 0, 2}};
    return p;
}
static void polarity_cases() {
    struct C { const char* n; bool want; } cs[] = {
        {"RESC1608X55N", false}, {"CAPC1608X90N", false}, {"INDC2012X100N", false}, {"RESMELF3515", false},
        {"FUSC3216X60N", false}, {"0603", false}, {"R0805", false}, {"C0402", false},
        {"DIOM5226X230N", true}, {"DIOC1608X80N", true}, {"DIOMELF3515", true}, {"SODFL3517X110N", true},
        {"LEDC2012X80N", true}, {"CAPMP3528X210N", true}, {"CAPAE530X550N", true}, {"SMA_DIODE", true},
    };
    for (auto& c : cs) {
        Package p = two_pad(c.n);
        std::string why;
        const bool got = pkg_default_polarity_reason(p, &why) > 0;
        CHECKM(got == c.want, std::string(c.n) + " -> " + why);
    }
    Package ic; ic.name = "SOIC127P600X175-8N";
    for (int i = 0; i < 8; ++i) ic.pads.push_back(Pad{{i < 4 ? -2.7 : 2.7, 1.905 - (i % 4) * 1.27}, 1.5, 0.6, 0, PadShape::Rect, 0, i + 1});
    CHECK(pkg_default_polarity_reason(ic, nullptr) > 0);
}

// multi-select edits: only the edited field changes, unchanged packages are skipped
static void multi_edit_cases() {
    Project p;
    Package a = two_pad("A"); a.height = 1; a.description = "keep-a"; a.smt = true;
    Package b = two_pad("B"); b.height = 2; b.description = "keep-b"; b.smt = false; b.pads[0].drill = 0.8;
    Package c = two_pad("C"); c.height = 3;
    pkg_add_polarity_marker(b);
    p.packages = {{"A", a}, {"B", b}, {"C", c}};
    auto ch = pkg_edit_many(p, {"A", "B"}, [](Package& q) { q.height = 5; });
    CHECK(ch.size() == 2);
    CHECK(p.packages["A"].height == 5 && p.packages["B"].height == 5 && p.packages["C"].height == 3);
    CHECK(p.packages["A"].description == "keep-a" && p.packages["B"].description == "keep-b");
    CHECK(p.packages["B"].smt == false && p.packages["B"].pads[0].drill == 0.8 && pkg_has_polarity(p.packages["B"]));
    ch = pkg_edit_many(p, {"A", "B"}, [](Package& q) { if (!pkg_has_polarity(q)) pkg_add_polarity_marker(q); });
    CHECK(ch.size() == 1 && ch[0] == "A");
    CHECK(pkg_has_polarity(p.packages["A"]) && !pkg_has_polarity(p.packages["C"]));
    ch = pkg_edit_many(p, {"A", "B", "C"}, [](Package& q) { q.smt = !pkg_detect_th(q); });
    CHECK(ch.empty());   // A smt, B drilled TH, C smt: already consistent
    p.packages["B"].smt = true;
    ch = pkg_edit_many(p, {"A", "B"}, [](Package& q) { q.smt = !pkg_detect_th(q); });
    CHECK(ch.size() == 1 && !p.packages["B"].smt);
    CHECK(shared_warning_many(p, {"A", "B"}).empty());
}

int main() {
    multi_edit_cases();
    odb_cases();
    ipc_cases();
    gencad_cases();
    kicad_cases();
    builder_cases();
    polarity_cases();
    std::printf("test_r18_import: %d passed, %d failed\n", g_pass, g_fail);
    return g_fail ? 1 : 0;
}
